  const settingBackground     = isChecked("Setting & background") ? RULES.settingBackground : DO_NOT_CHECK;
  const distractingElements   = isChecked("Distracting elements") ? RULES.distractingElements : DO_NOT_CHECK;
  const safeZones             = isChecked("Safe zones") ? "Safe zones" : DO_NOT_CHECK;
  const watchableOnMute       = isChecked("Watchable on mute") ? "Watchable on mute" : DO_NOT_CHECK;
  const energyAuthenticity    = isChecked("Energy & authenticity") ? RULES.energyAuthenticity : DO_NOT_CHECK;
  const wardrobeAppearance    = isChecked("Wardrobe & appearance") ? RULES.wardrobeAppearance : DO_NOT_CHECK;
  const productUsage          = isChecked("Product usage") ? RULES.productUsage : DO_NOT_CHECK;
  const inspirationLinkMatch  = isChecked("Inspiration link match") ? RULES.inspirationLinkMatch : DO_NOT_CHECK;

  return {
    checkedItems,
    brandBio,
    brandVoice,
    brandCta,
    targetAudience,
    painPoints,
    objectives,
    niche,
    briefAttachment,
    submissionNotes,
    videoFormat,
    videoSize,
    videoResolution,
    videoAspectRatio,
    videoFrameRate,
    videoDuration,
    productScreenTime,
    hookSpeed,
    visualHook,
    ctaPlacement,
    faceTime,
    textLegibility,
    audioClarity,
    engagementPacing,
    brandMentions,
    brandBriefAlignment,
    copyright,
    closedCaptions,
    followsTheBrief,
    audioDelivery,
    pronunciation,
    musicSoundBalance,
    lightingCamera,
    settingBackground,
    distractingElements,
    safeZones,
    watchableOnMute,
    energyAuthenticity,
    wardrobeAppearance,
    productUsage,
    inspirationLinkMatch
  };
});
return brief;

// Get the Vertex AI response
const items = $input.all();

return items.map(item => {
  const response = item.json.candidates[0].content.parts[0].text;

  // Strip markdown code blocks if present
  let cleanJson = response.trim();
  if (cleanJson.startsWith('```json')) {
    cleanJson = cleanJson.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  }

  // Parse the JSON
  const parsed = JSON.parse(cleanJson);

  // Return as ONE ITEM with analysis as nested array
  return {
    json: {
      overall_review: parsed.overall_review,
      analysis: parsed.analysis, // Keep as array
      transcript: parsed.transcript
    }
  };
});

// Get the review ID that was just created
const reviewId = $('Review5').first().json.id;

// Get the analysis array from the original parsed data
// Reference back to the Code node before Review
const analysis = $('Code in JavaScript10').first().json.analysis;

// Create 11 items (one for each threshold)
return analysis.map(threshold => {
  return {
    json: {
      review_id: reviewId,
      threshold_name: threshold.threshold_name,
      score: threshold.score,
      value: threshold.value,
      status: threshold.status,
      rating: threshold.rating,
      severity: threshold.severity,
      comment: threshold.comment,
      key_moment_timestamp: threshold.key_moment_timestamp,
      screenshot_url: threshold.screenshot_url
    }
  };
});

// Get account ID from both possible locations
const accountId1 = $input.first().json.account_id?.[0];
const accountId2 = $input.first().json.accounts?.id;

// Pick the first non-empty/non-undefined account ID
const accountId = accountId1 || accountId2 || "";

// Return the account ID
return {
  json: {
    account_id: accountId
  }
};

const submission = $('Get Submission').first().json;

// normalise files
const videoFiles = Array.isArray(submission.video_file || [])
  ? submission.video_file
  : [submission.video_file].filter(Boolean);
const videoCount = videoFiles.length;

// submission type
const submissionType = submission.submission_type || '';
const isLinkSubmission = submissionType === 'link';

// --- BULK VIDEO URLS (NEW) ---
const bulkVideoUrlRaw = submission.bulk_video_url || null;
let bulkVideoUrls = [];
if (Array.isArray(bulkVideoUrlRaw)) {
  bulkVideoUrls = bulkVideoUrlRaw.filter(Boolean);
} else if (typeof bulkVideoUrlRaw === 'string' && bulkVideoUrlRaw.trim()) {
  bulkVideoUrls = bulkVideoUrlRaw.split(/[\r\n]+/).map(u => u.trim()).filter(Boolean);
}
const bulkVideoCount = bulkVideoUrls.length;

// --- LOGIC FIELD (NEW) ---
const logicRaw = submission.logic || '';
const logicLabel = typeof logicRaw === 'object'
  ? (logicRaw.label || '')
  : logicRaw;

// --- ACCOUNT DATA ---
const accountJson = $input.first().json;

// --- CREDITS REMAINING ---
const creditsRaw = accountJson['video_credits']
  ?? accountJson['videos_remaining (usage)']
  ?? accountJson['videos_remaining']
  ?? 0;

let creditsRemaining;
if (Array.isArray(creditsRaw)) {
  creditsRemaining = Number(creditsRaw[0] ?? 0);
} else {
  creditsRemaining = Number(creditsRaw ?? 0);
}
if (!Number.isFinite(creditsRemaining)) creditsRemaining = 0;

// --- PAYMENT STATUS ---
const paymentRaw = accountJson['payment_status (billing)']
  ?? accountJson['payment_status']
  ?? '';

let paymentStatus;
if (Array.isArray(paymentRaw) && paymentRaw.length > 0) {
  paymentStatus = String(paymentRaw[0].label ?? paymentRaw[0] ?? '').trim().toLowerCase();
} else if (typeof paymentRaw === 'object' && paymentRaw !== null) {
  paymentStatus = String(paymentRaw.label ?? '').trim().toLowerCase();
} else {
  paymentStatus = String(paymentRaw).trim().toLowerCase();
}

const hasActivePlan = paymentStatus === 'paid';
const hasEnoughCredits = creditsRemaining > 0;
const isBulk = /bulk/i.test(logicLabel) || videoCount > 1 || bulkVideoCount > 0;

// --- SUBMISSION TYPE DETECTION ---
const detectType = (url) => {
  if (!url) return 'upload';
  const lower = url.toLowerCase();
  if (lower.includes('tiktok.com')) return 'TikTok';
  if (lower.includes('instagram.com')) return 'Instagram';
  return 'upload';
};

const singleType = isLinkSubmission
  ? detectType(submission.video_link || submission.video_url || '')
  : 'upload';

const baseMeta = {
  submissionId: submission.id,
  creatorEmail: submission.creator_email || null,
  creatorName: submission.creator_name || null,
  users: submission.users || null,
  accounts: submission.accounts,
  creditsRemaining,
  videoCount,
  isBulk,
  hasActivePlan,
  hasEnoughCredits,
  paymentStatus,
};

// 1) No active plan
if (!hasActivePlan) {
  return [
    {
      json: {
        ...baseMeta,
        type: singleType,
        system_title: 'Video not reviewed',
        system_message:
          'Your video was not reviewed because there is no active payment plan on this account. Please update your billing to continue.',
      },
    },
  ];
}

// 2) Not enough credits
if (!hasEnoughCredits) {
  return [
    {
      json: {
        ...baseMeta,
        type: singleType,
        system_title: 'Video not reviewed',
        system_message:
          'Your video was not reviewed because there are not enough credits on this account. Please top up your credits and try again.',
      },
    },
  ];
}

// 3) No files (only if not a link submission and not bulk)
if (!isLinkSubmission && !isBulk && videoCount === 0) {
  return [
    {
      json: {
        ...baseMeta,
        type: singleType,
        system_title: 'Video not reviewed',
        system_message:
          'Your video was not reviewed because no video file was found in your submission. Please upload a video or provide a valid link and try again.',
      },
    },
  ];
}

// 4) Single or link submission
if (!isBulk) {
  return [
    {
      json: {
        ...submission,
        hasActivePlan: true,
        hasEnoughCredits: true,
        paymentStatus,
        isBulk: false,
        type: singleType,
        videoCount,
        creditsRemaining,
        system_title: 'Video received',
        system_message:
          "Your video is being reviewed. You'll receive results shortly.",
      },
    },
  ];
}

// 5) Bulk upload — video files
if (videoCount > 0) {
  const items = videoFiles.map((file, index) => ({
    json: {
      hasActivePlan: true,
      hasEnoughCredits: true,
      paymentStatus,
      isBulk: true,
      type: 'upload',
      parentSubmissionId: submission.id,
      creator_name: submission.creator_name || null,
      creator_email: submission.creator_email || null,
      users: submission.users || null,
      submission_type: submission.submission_type,
      submission_notes: submission.submission_notes || null,
      brief_attachment: submission.brief_attachment || null,
      accounts: submission.accounts,
      projects: submission.projects || null,
      briefs: submission.briefs || null,
      video_file: [file],
      bulkIndex: index + 1,
      bulkTotal: videoCount,
      creditsRemaining,
      fileName: file.filename || file.name || `video_${index + 1}`,
      fileUrl: file.url,
      fileSize: file.size || null,
      system_title: index === 0 ? 'Bulk upload received' : null,
      system_message:
        index === 0
          ? `${videoCount} videos are being reviewed. You'll receive results for each video as they complete.`
          : null,
    },
  }));
  return items;
}

// 6) Bulk upload — video URLs
return bulkVideoUrls.map((url, index) => ({
  json: {
    hasActivePlan: true,
    hasEnoughCredits: true,
    paymentStatus,
    isBulk: true,
    type: detectType(url),
    parentSubmissionId: submission.id,
    creator_name: submission.creator_name || null,
    creator_email: submission.creator_email || null,
    users: submission.users || null,
    submission_type: submission.submission_type,
    submission_notes: submission.submission_notes || null,
    brief_attachment: submission.brief_attachment || null,
    accounts: submission.accounts,
    projects: submission.projects || null,
    briefs: submission.briefs || null,
    bulk_video_url: url,
    bulkIndex: index + 1,
    bulkTotal: bulkVideoCount,
    creditsRemaining,
    fileName: `Video ${index + 1} of ${bulkVideoCount}`,
    fileUrl: url,
    system_title: index === 0 ? 'Bulk upload received' : null,
    system_message:
      index === 0
        ? `${bulkVideoCount} videos are being reviewed. You'll receive results for each video as they complete.`
        : null,
  },
}));

